CREATE   PROCEDURE [synapse_ce].[usp_Update_letter]
AS
BEGIN

	;WITH cte AS
	(
		SELECT 
		stg.[activityid],
		stg.[activitytypecode],
		stg.[actualdurationminutes],
		stg.[actualend],
		stg.[actualstart],
		stg.[address],
		stg.[apitil_public],
		stg.[apitil_ticket],
		stg.[apitil_ticket_entitytype],
		stg.[apitil_ticketname],
		stg.[apuk_relevant],
		stg.[apuk_sensitive],
		stg.[bcc],
		stg.[category],
		stg.[cc],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[directioncode],
		stg.[exchangerate],
		stg.[from],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[isbilled],
		stg.[isregularactivity],
		stg.[isworkflowcreated],
		stg.[lastonholdtime],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[onholdtime],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[prioritycode],
		stg.[processid],
		stg.[regardingobjectid],
		stg.[regardingobjectid_entitytype],
		stg.[regardingobjectidname],
		stg.[regardingobjectidyominame],
		stg.[regardingobjecttypecode],
		stg.[scheduleddurationminutes],
		stg.[scheduledend],
		stg.[scheduledstart],
		stg.[serviceid],
		stg.[serviceid_entitytype],
		stg.[serviceidname],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[slaid],
		stg.[slaid_entitytype],
		stg.[slainvokedid],
		stg.[slainvokedid_entitytype],
		stg.[slainvokedidname],
		stg.[slaname],
		stg.[sortdate],
		stg.[stageid],
		stg.[statecode],
		stg.[statuscode],
		stg.[subcategory],
		stg.[subject],
		stg.[subscriptionid],
		stg.[timezoneruleversionnumber],
		stg.[to],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[traversedpath],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber],	
		ROW_NUMBER() OVER(PARTITION BY ID ORDER BY modifiedon DESC) AS RowNo
		FROM [staging_ce].[letter] stg
	)



	UPDATE tgt SET 
		tgt.[activityid] = stg.[activityid],
		tgt.[activitytypecode] = stg.[activitytypecode],
		tgt.[actualdurationminutes] = stg.[actualdurationminutes],
		tgt.[actualend] = stg.[actualend],
		tgt.[actualstart] = stg.[actualstart],
		tgt.[address] = stg.[address],
		tgt.[apitil_public] = stg.[apitil_public],
		tgt.[apitil_ticket] = stg.[apitil_ticket],
		tgt.[apitil_ticket_entitytype] = stg.[apitil_ticket_entitytype],
		tgt.[apitil_ticketname] = stg.[apitil_ticketname],
		tgt.[apuk_relevant] = stg.[apuk_relevant],
		tgt.[apuk_sensitive] = stg.[apuk_sensitive],
		tgt.[bcc] = stg.[bcc],
		tgt.[category] = stg.[category],
		tgt.[cc] = stg.[cc],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[description] = stg.[description],
		tgt.[directioncode] = stg.[directioncode],
		tgt.[exchangerate] = stg.[exchangerate],
		tgt.[from] = stg.[from],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[isbilled] = stg.[isbilled],
		tgt.[isregularactivity] = stg.[isregularactivity],
		tgt.[isworkflowcreated] = stg.[isworkflowcreated],
		tgt.[lastonholdtime] = stg.[lastonholdtime],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[onholdtime] = stg.[onholdtime],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[ownerid] = stg.[ownerid],
		tgt.[ownerid_entitytype] = stg.[ownerid_entitytype],
		tgt.[owneridname] = stg.[owneridname],
		tgt.[owneridtype] = stg.[owneridtype],
		tgt.[owneridyominame] = stg.[owneridyominame],
		tgt.[owningbusinessunit] = stg.[owningbusinessunit],
		tgt.[owningbusinessunit_entitytype] = stg.[owningbusinessunit_entitytype],
		tgt.[owningbusinessunitname] = stg.[owningbusinessunitname],
		tgt.[owningteam] = stg.[owningteam],
		tgt.[owningteam_entitytype] = stg.[owningteam_entitytype],
		tgt.[owninguser] = stg.[owninguser],
		tgt.[owninguser_entitytype] = stg.[owninguser_entitytype],
		tgt.[prioritycode] = stg.[prioritycode],
		tgt.[processid] = stg.[processid],
		tgt.[regardingobjectid] = stg.[regardingobjectid],
		tgt.[regardingobjectid_entitytype] = stg.[regardingobjectid_entitytype],
		tgt.[regardingobjectidname] = stg.[regardingobjectidname],
		tgt.[regardingobjectidyominame] = stg.[regardingobjectidyominame],
		tgt.[regardingobjecttypecode] = stg.[regardingobjecttypecode],
		tgt.[scheduleddurationminutes] = stg.[scheduleddurationminutes],
		tgt.[scheduledend] = stg.[scheduledend],
		tgt.[scheduledstart] = stg.[scheduledstart],
		tgt.[serviceid] = stg.[serviceid],
		tgt.[serviceid_entitytype] = stg.[serviceid_entitytype],
		tgt.[serviceidname] = stg.[serviceidname],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[slaid] = stg.[slaid],
		tgt.[slaid_entitytype] = stg.[slaid_entitytype],
		tgt.[slainvokedid] = stg.[slainvokedid],
		tgt.[slainvokedid_entitytype] = stg.[slainvokedid_entitytype],
		tgt.[slainvokedidname] = stg.[slainvokedidname],
		tgt.[slaname] = stg.[slaname],
		tgt.[sortdate] = stg.[sortdate],
		tgt.[stageid] = stg.[stageid],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[subcategory] = stg.[subcategory],
		tgt.[subject] = stg.[subject],
		tgt.[subscriptionid] = stg.[subscriptionid],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[to] = stg.[to],
		tgt.[transactioncurrencyid] = stg.[transactioncurrencyid],
		tgt.[transactioncurrencyid_entitytype] = stg.[transactioncurrencyid_entitytype],
		tgt.[transactioncurrencyidname] = stg.[transactioncurrencyidname],
		tgt.[traversedpath] = stg.[traversedpath],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM cte tgt--[synapse_ce].[letter] tgt
		INNER JOIN [staging_ce].[letter] stg
			ON tgt.[id] = stg.[id]
	WHERE tgt.[RowNo] = 1
END
